<?php $linkedProjects=$teamProjects[$team['id']]??[]; $linkedIds=array_column($linkedProjects,'id'); ?>
<div class="team-projects"><h4>Projets de l’équipe</h4>
<?php foreach($linkedProjects as $linked): ?><div class="team-project-row"><a href="/list?project=<?= (int)$linked['id'] ?>&team=<?= (int)$team['id'] ?>"><?= e($linked['name']) ?> <small><?= e($linked['project_key']) ?></small></a><?php if($isAdmin): ?><form method="post" action="/teams/<?= (int)$team['id'] ?>/projects"><?= csrf() ?><input type="hidden" name="_return" value="/settings#teams"><input type="hidden" name="project_id" value="<?= (int)$linked['id'] ?>"><input type="hidden" name="action" value="remove"><button class="text-button" aria-label="Retirer le projet <?= e($linked['name']) ?> de <?= e($team['name']) ?>">Retirer</button></form><?php endif; ?></div><?php endforeach; ?>
<?php if(!$linkedProjects): ?><p class="muted">Aucun projet associé.</p><?php endif; ?>
<a class="text-button" href="/all?team=<?= (int)$team['id'] ?>">Voir tous les tickets de cette équipe</a>
<?php if($isAdmin): $availableProjects=array_filter($projects,fn($p)=>!in_array($p['id'],$linkedIds,true)); if($availableProjects): ?><form method="post" action="/teams/<?= (int)$team['id'] ?>/projects" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/settings#teams"><input type="hidden" name="action" value="add"><label>Associer un projet à <?= e($team['name']) ?><select name="project_id" required><option value="">Choisir un projet</option><?php foreach($availableProjects as $candidate): ?><option value="<?= (int)$candidate['id'] ?>"><?= e($candidate['name']) ?></option><?php endforeach; ?></select></label><button class="button subtle">Associer le projet</button></form><?php endif; endif; ?>
</div>
